import torch
import torch.nn as nn
import torch.nn.functional as F
from torch.utils.cpp_extension import load_inline

# Inline CUDA/C++ code for fused linear + division + GELU
fused_source = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <math.h>

// Approximate GELU (matching PyTorch's approximation)
__device__ __forceinline__ float approximate_gelu(float x) {
    const float kAlpha = 0.044715f;
    const float kSqrt2OverPi = 0.7978845608f; // sqrt(2.0 / M_PI)
    float x3 = x * x * x;
    float inner = kSqrt2OverPi * (x + kAlpha * x3);
    return 0.5f * x * (1.0f + tanhf(inner));
}

__global__ void fused_linear_div_gelu_kernel(const float* __restrict__ x,
                                            const float* __restrict__ w,
                                            const float* __restrict__ b,
                                            float divisor,
                                            float* __restrict__ out,
                                            int B, int I, int O) {
    int tid = blockIdx.x * blockDim.x + threadIdx.x;
    int total = B * O;
    if (tid < total) {
        int b_idx = tid / O;
        int o_idx = tid % O;
        float val = 0.0f;
        // Matrix multiplication: x[b_idx, :] dot w[o_idx, :]
        for (int i = 0; i < I; i++) {
            val += x[b_idx * I + i] * w[o_idx * I + i];
        }
        // Add bias
        val += b[o_idx];
        // Divide by scalar
        val /= divisor;
        // Apply GELU
        val = approximate_gelu(val);
        out[tid] = val;
    }
}

torch::Tensor fused_linear_div_gelu(torch::Tensor x,
                                    torch::Tensor weight,
                                    torch::Tensor bias,
                                    double divisor) {
    // Dimensions
    auto B = x.size(0);
    auto I = x.size(1);
    auto O = weight.size(0);
    auto out = torch::empty({B, O}, x.options());

    int threads = 256;
    int blocks = (B * O + threads - 1) / threads;

    fused_linear_div_gelu_kernel<<<blocks, threads>>>(
        x.data_ptr<float>(),
        weight.data_ptr<float>(),
        bias.data_ptr<float>(),
        static_cast<float>(divisor),
        out.data_ptr<float>(),
        B, I, O
    );
    return out;
}
"""

fused_cpp_source = r"""
torch::Tensor fused_linear_div_gelu(torch::Tensor x,
                                    torch::Tensor weight,
                                    torch::Tensor bias,
                                    double divisor);
"""

# Build/Load the inline CUDA extension
fused_module = load_inline(
    name="fused_ops",
    cpp_sources=fused_cpp_source,
    cuda_sources=fused_source,
    functions=["fused_linear_div_gelu"],
    verbose=False,
)

class ModelNew(nn.Module):
    """
    Optimized model that fuses the linear layer, division, and GELU into a single custom CUDA kernel.
    """
    def __init__(self, input_size, output_size, divisor):
        super(ModelNew, self).__init__()
        # We'll still hold a Linear layer to manage weights and biases
        self.linear = nn.Linear(input_size, output_size)
        self.divisor = divisor
        self.fused_kernel = fused_module

    def forward(self, x):
        # Call the fused kernel directly
        return self.fused_kernel.fused_linear_div_gelu(
            x, self.linear.weight, self.linear.bias, self.divisor
        )
